def matches(path: str, pattern: str) -> bool:
    # Wildcards apply within a single path segment and never cross "/".
    path_segments = path.split("/")
    pattern_segments = pattern.split("/")
    if len(path_segments) != len(pattern_segments):
        return False
    return all(fnmatchcase(p, q) for p, q in zip(path_segments, pattern_segments))

